import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

# Longest-first alternation so "sec" never matches as bare "s".
_UNIT_RE = r"seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d"
_PART_RE = re.compile(r"(\d+)\s*(" + _UNIT_RE + r")", re.I)
_FULL_RE = re.compile(r"(?:\d+\s*(?:" + _UNIT_RE + r")\s*)+", re.I)


def parse_duration(text):
    """Parse a duration string like "1d 6h 30m" (or a bare "90") into seconds."""
    s = text.strip()
    if s.isdigit():
        return int(s)
    if not _FULL_RE.fullmatch(s):
        raise ValueError("could not parse duration: {!r}".format(text))
    return sum(int(n) * _UNITS[u.lower()] for n, u in _PART_RE.findall(s))
```

The regex does the branching, so the function itself is complexity 3-4: validate the whole string with one `fullmatch`, then sum the number/unit pairs. Bare digits are special-cased up front so `"90"` means seconds while `"90x"` still fails.

Note `s.isdigit()` is true for some non-ASCII digit characters (e.g. `"٩٠"`), which `int()` accepts too — swap in `re.fullmatch(r"\d+", s)` plus an ASCII-only check if you need strictness there.

