import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

_TOKEN = re.compile(r"\s*(\d+)\s*([a-z]*)")


def parse_duration(text):
    """Parse a duration string like '1d 6h 30m', '90s' or a bare '90' into seconds."""
    def bad():
        return ValueError(f"could not parse duration: {text!r}")

    if not isinstance(text, str):
        raise bad()

    s = text.strip().lower()
    if not s:
        raise bad()

    total = 0
    pos = 0
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise bad()
        number, unit = m.group(1), m.group(2)
        if unit:
            if unit not in _UNITS:
                raise bad()
            total += int(number) * _UNITS[unit]
        else:
            # A unitless number means seconds, but only if it's the whole input.
            if pos != 0 or m.end() != len(s):
                raise bad()
            total += int(number)
        pos = m.end()

    return total
```

