    """Parse a duration string like '1d 6h 30m', '90s' or '90' into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")

    cleaned = text.strip().lower()

    if cleaned.isdigit():
        return int(cleaned)

    if not _WHOLE.fullmatch(cleaned):
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    for amount, unit in _COMPONENT.findall(cleaned):
        if unit not in _UNITS:
            raise ValueError(f"invalid duration: {text!r}")
        total += int(amount) * _UNITS[unit]
    return total
